mkdir -p /tmp/ops/data && cat > /tmp/ops/ems.py <<'EOF'
import json, urllib.request, urllib.error, sys
BASE="http://ems-sim:8080/api/v1"
def get(path, **params):
    q="&".join(f"{k}={v}" for k,v in params.items())
    url=f"{BASE}/{path}"+("?"+q if q else "")
    try:
        with urllib.request.urlopen(url, timeout=30) as r:
            return r.status, json.loads(r.read())
    except urllib.error.HTTPError as e:
        try: body=json.loads(e.read())
        except Exception: body=None
        return e.code, body
def post(path, body):
    req=urllib.request.Request(f"{BASE}/{path}", data=json.dumps(body).encode(), headers={"Content-Type":"application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, json.loads(r.read())
    except urllib.error.HTTPError as e:
        try: body=json.loads(e.read())
        except Exception: body=None
        return e.code, body
if __name__=="__main__":
    print(json.dumps(get(sys.argv[1], **dict(a.split("=",1) for a in sys.argv[2:])), indent=1))
EOF
cat > /tmp/ops/poller.py <<'EOF'
import json, time, sys
sys.path.insert(0,"/tmp/ops")
from ems import get
D="/tmp/ops/data/"
def save(name,obj):
    with open(D+name+".tmp","w") as f: json.dump(obj,f)
    import os; os.replace(D+name+".tmp", D+name)
i=0
while True:
    try:
        s=get("status"); save("status.json", s)
        with open(D+"status_log.jsonl","a") as f: f.write(json.dumps([time.time(),s])+"\n")
        if i%2==0:
            save("telemetry.json", get("telemetry", from_hour=0))
            save("events.json", get("events", from_hour=0))
            save("messages.json", get("messages"))
        if s[0]==200 and s[1].get("plant_hour",0)>=72.05: break
    except Exception as e:
        print("err",e, flush=True)
    i+=1
    time.sleep(60)
EOF
